package net.minecraft.network;
import java.util.*;import net.minecraft.core.BlockPos;public class RegistryFriendlyByteBuf {public final List<Object> values=new ArrayList<>();public final List<Integer> bounds=new ArrayList<>();private int cursor;public void writeBlockPos(BlockPos p){values.add(p);}public BlockPos readBlockPos(){return (BlockPos)values.get(cursor++);}public void writeUtf(String s,int max){if(s.length()>max)throw new IllegalArgumentException("bound");values.add(s);bounds.add(max);}public String readUtf(int max){String v=(String)values.get(cursor++);if(v.length()>max)throw new IllegalArgumentException("bound");return v;}}
